import math
from scipy.optimize import minimize_scalar

def f(x):
    if x < 0 or x > 1:
        return -float('inf')
    if x == 1:
        return 1.0
    if x == 0:
        return 0.0
    # f(x) = x + (1-x)^(1/3) * x^(2/3)
    return x + ((1 - x)**(1/3)) * (x**(2/3))

# Find the maximum of f(x) in the interval [0, 1]
# We minimize -f(x)
result = minimize_scalar(-f, bounds=(0, 1), method='bounded')

x_opt = result.x
f_max = -result.fun

print(f"Optimal x: {x_opt}")
print(f"Maximum f(x): {f_max}")

