import math
from scipy.optimize import minimize_scalar

def f(x):
    if x < 0 or x > 1:
        return -float('inf')
    if x == 1:
        return 1.0
    if x == 0:
        return 0.0
    # f(x) = x + (1-x)^(1/3) * x^(2/3)
    return x + ((1 - x)**(1/3)) * (x**(2/3))

# The function to minimize is g(x) = -f(x)
def g(x):
    return -f(x)

# Find the minimum of g(x) in the interval [0, 1]
result = minimize_scalar(g, bounds=(0, 1), method='bounded')

